package com.yuwatang.reservation;

import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.http.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.transaction.annotation.Transactional;
import org.apache.poi.ss.usermodel.*;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import javax.imageio.ImageIO;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import static com.yuwatang.reservation.Data.*;

@RestController @RequestMapping("/api/admin")
class FilesApi {
    final Data d;final AuthService auth;final AdminService admin;final CatalogService catalog;final String dataDir;
    FilesApi(Data d,AuthService auth,AdminService admin,CatalogService catalog,@Value("${app.data-dir}")String dataDir){this.d=d;this.auth=auth;this.admin=admin;this.catalog=catalog;this.dataDir=dataDir;}
    @GetMapping("/assets") @Permit("assets:read")List<Map<String,Object>> assets(HttpServletRequest r){var a=auth.admin(r);List<Map<String,Object>> out=new ArrayList<>();for(var v:catalog.collection(d.object(d.one("SELECT published_json FROM site_config WHERE id='brand'").get("publishedJson")),"assetLibrary"))out.add(v);out.addAll(d.rows("SELECT * FROM asset"+(a.hq()?"":" WHERE store_id IS NULL OR store_id=?")+" ORDER BY created_at DESC",a.hq()?new Object[]{}:new Object[]{a.storeId()}));return out;}
    @PostMapping("/assets") @Permit("assets:write")Map<String,Object> upload(HttpServletRequest r,@RequestPart MultipartFile file,@RequestParam(defaultValue="")String storeId)throws IOException{var a=auth.admin(r);String store=admin.scope(a,storeId);if(file.isEmpty()||file.getSize()>5*1024*1024)throw error(400,"请上传不超过5MB的图片。");byte[] bytes=file.getBytes();String ext;if(bytes.length>=12&&bytes[0]=='R'&&bytes[1]=='I'&&bytes[2]=='F'&&bytes[3]=='F'&&bytes[8]=='W'&&bytes[9]=='E'&&bytes[10]=='B'&&bytes[11]=='P')ext="webp";else{var img=ImageIO.read(new ByteArrayInputStream(bytes));if(img==null||img.getWidth()>12000||img.getHeight()>12000||((long)img.getWidth()*img.getHeight())>40000000)throw error(400,"图片无法读取或尺寸过大，仅支持JPG、PNG、WebP。");if(bytes.length>8&&bytes[0]==(byte)0x89&&bytes[1]=='P'&&bytes[2]=='N'&&bytes[3]=='G')ext="png";else if(bytes[0]==(byte)0xff&&bytes[1]==(byte)0xd8)ext="jpg";else throw error(400,"仅支持JPG、PNG、WebP图片。");}
        String id=id(),name=id+"."+ext,title=Objects.requireNonNullElse(file.getOriginalFilename(),"门店图片");title=title.substring(0,Math.min(100,title.length()));Path root=Path.of(dataDir,"uploads").toAbsolutePath().normalize();Files.createDirectories(root);Path target=root.resolve(name).normalize();if(!target.startsWith(root))throw error(400,"文件名无效。");Files.write(target,bytes,StandardOpenOption.CREATE_NEW);try{d.update("INSERT INTO asset VALUES(?,?,?,?,?)",id,store.isEmpty()?null:store,title,"/uploads/"+name,now());}catch(RuntimeException e){Files.deleteIfExists(target);throw e;}d.audit(a,store,"asset.upload",id,"上传授权门店图片");return Map.of("id",id,"url","/uploads/"+name,"title",title);}
    ResponseEntity<byte[]> workbook(String name,List<String> headers,List<List<Object>> rows)throws IOException{try(var book=new XSSFWorkbook();var out=new ByteArrayOutputStream()){var sheet=book.createSheet("资料");var style=book.createCellStyle();var font=book.createFont();font.setBold(true);font.setColor(IndexedColors.WHITE.getIndex());style.setFont(font);style.setFillForegroundColor(IndexedColors.DARK_GREEN.getIndex());style.setFillPattern(FillPatternType.SOLID_FOREGROUND);var h=sheet.createRow(0);for(int i=0;i<headers.size();i++){h.createCell(i).setCellValue(headers.get(i));h.getCell(i).setCellStyle(style);sheet.setColumnWidth(i,Math.min(60,Math.max(18,headers.get(i).length()+5))*256);}int ri=1;for(var record:rows){var row=sheet.createRow(ri++);for(int i=0;i<record.size();i++){Object value=record.get(i);row.createCell(i).setCellValue(value==null?"":value.toString());}}sheet.createFreezePane(0,1);book.write(out);return ResponseEntity.ok().contentType(MediaType.parseMediaType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(name,java.nio.charset.StandardCharsets.UTF_8).build().toString()).body(out.toByteArray());}}
    @GetMapping("/exports/appointments") @Permit("appointments:export")ResponseEntity<byte[]> exportAppointments(HttpServletRequest r,@RequestParam Map<String,String> filters)throws IOException{var a=auth.admin(r);AdminService.hq(a);var q=admin.appointmentQuery(a,filters);if(d.count("SELECT COUNT(*) FROM appointment"+q.where(),q.args().toArray())>10000)throw error(400,"单次导出最多10000笔，请缩小日期范围。");var rows=d.rows("SELECT id,store_id,service_name,customer_name,phone,booking_date,start_time,headcount,therapist_intent_name,status,source,member_claim FROM appointment"+q.where()+" ORDER BY booking_date,start_time",q.args().toArray());List<List<Object>> records=new ArrayList<>();for(var row:rows){List<Object> cells=new ArrayList<>();for(String key:List.of("id","storeId","serviceName","customerName","phone","bookingDate","startTime","headcount","therapistIntentName","status","source","memberClaim"))cells.add(row.get(key));records.add(cells);}d.audit(a,filters.get("storeId"),"appointment.export","appointments","行数="+rows.size()+"；含完整电话");return workbook("裕和堂-预约记录.xlsx",List.of("预约编号","门店编号","项目","称呼","电话","日期","开始时间","人数","意向调理师","状态","来源","会员自述"),records);}
    @GetMapping("/exports/customers") @Permit("customers:export")ResponseEntity<byte[]> exportCustomers(HttpServletRequest r,@RequestParam(defaultValue="")String storeId)throws IOException{
        var actor=auth.admin(r);AdminService.hq(actor);String sid=admin.scope(actor,storeId);
        var rows=d.rows("SELECT cp.id,cp.name,cp.phone,cp.member_verified,cp.member_grade,sc.store_id,sc.source FROM customer_profile cp LEFT JOIN store_customer sc ON sc.customer_profile_id=cp.id"+(sid.isBlank()?"":" WHERE sc.store_id=?")+" ORDER BY cp.created_at DESC LIMIT 10000",sid.isBlank()?new Object[]{}:new Object[]{sid});
        List<List<Object>> records=new ArrayList<>();Map<String,List<String>> sourceMap=new HashMap<>();
        for(var source:d.rows("SELECT customer_profile_id,source FROM customer_source ORDER BY source"))sourceMap.computeIfAbsent(str(source,"customerProfileId"),key->new ArrayList<>()).add(str(source,"source"));
        Map<String,String> labels=Map.of("MINIPROGRAM","小程序","DIANPING","大众点评","WECHAT","微信","PHONE","电话","WALKIN","到店","IMPORT","资料导入");
        for(var row:rows){
            var sources=new LinkedHashSet<>(sourceMap.getOrDefault(str(row,"id"),List.of()));if(!str(row,"source").isBlank())sources.add(str(row,"source"));
            records.add(Arrays.asList(row.get("name"),row.get("phone"),bool(row,"memberVerified")?"会员":"非会员",row.get("memberGrade"),row.get("storeId"),String.join("、",sources.stream().map(source->labels.getOrDefault(source,source)).toList())));
        }
        d.audit(actor,sid,"customer.export","customers","行数="+rows.size()+"；含完整联系电话；不含私有跟进");
        return workbook("裕和堂-客户基础资料.xlsx",List.of("称呼","电话","会员状态","会员等级","门店编号","客户来源"),records);
    }

    static final Map<String,List<String>> HEADERS=Map.of(
        "members",List.of("name","phone","storeId","memberVerified","memberGrade","externalId"),
        "therapists",List.of("id","name","storeId","grade","specialty","serviceIds","enabled","showOnClient","resting"),
        "stores",List.of("id","name","district","address","phone","hours","image"),
        "services",List.of("id","name","subtitle","category","duration","image","description","enabled"));
    List<String> headers(String kind){var h=HEADERS.get(kind);if(h==null)throw error(404,"导入类型不存在。");return h;}
    @GetMapping("/imports/{kind}/template") @Permit("imports:write")ResponseEntity<byte[]> template(HttpServletRequest r,@PathVariable String kind)throws IOException{AdminService.hq(auth.admin(r));return workbook("裕和堂-"+kind+"-模板.xlsx",headers(kind),List.of());}
    List<Map<String,Object>> parse(MultipartFile file,List<String> headers)throws IOException{if(file.isEmpty()||file.getSize()>5*1024*1024)throw error(400,"请选择5MB内的xlsx资料表。");List<Map<String,Object>> rows=new ArrayList<>();try(var book=new XSSFWorkbook(file.getInputStream())){var sheet=book.getSheetAt(0);if(sheet.getLastRowNum()>5000)throw error(400,"单次最多5000条资料。");var format=new DataFormatter(Locale.ROOT);var first=sheet.getRow(0);if(first==null)throw error(400,"缺少模板列标题。");for(int i=0;i<headers.size();i++)if(!headers.get(i).equals(format.formatCellValue(first.getCell(i)).trim()))throw error(400,"模板列不匹配，请重新下载模板："+headers.get(i));for(int i=1;i<=sheet.getLastRowNum();i++){var row=sheet.getRow(i);if(row==null)continue;Map<String,Object> values=new LinkedHashMap<>();for(int j=0;j<headers.size();j++){var cell=row.getCell(j);if(cell!=null&&cell.getCellType()==CellType.FORMULA)throw error(400,"第"+(i+1)+"行包含公式，请粘贴为纯值。");values.put(headers.get(j),format.formatCellValue(cell).trim());}if(values.values().stream().anyMatch(v->!v.toString().isBlank())){values.put("_row",i+1);rows.add(values);}}}catch(org.apache.poi.ooxml.POIXMLException e){throw error(400,"无法读取xlsx文件，请检查是否为有效模板。");}return rows;}
    boolean flag(Map<String,Object> row,String key,boolean fallback){String s=str(row,key);if(s.isBlank())return fallback;if(!Set.of("true","false","1","0","是","否").contains(s))throw error(400,key+"须填写true/false或是/否");return Set.of("true","1","是").contains(s);}
    @PostMapping("/imports/{kind}") @Permit("imports:write") @Transactional public Map<String,Object> importData(HttpServletRequest r,@PathVariable String kind,@RequestParam(defaultValue="false")boolean commit,@RequestPart MultipartFile file)throws IOException{var a=auth.admin(r);AdminService.hq(a);var rows=parse(file,headers(kind));List<String> errors=new ArrayList<>();Set<String> unique=new HashSet<>();if(rows.isEmpty())errors.add("请至少填写一行资料。");for(var row:rows)try{String name=text(row,"name",1,60);if(kind.equals("members")){String phone=text(row,"phone",11,11);if(!phone.matches("1[3-9]\\d{9}"))throw error(400,"手机号应为11位数字");catalog.store(text(row,"storeId",1,64));flag(row,"memberVerified",false);text(row,"memberGrade",0,60);text(row,"externalId",0,80);if(!unique.add(phone))throw error(400,"文件内手机号重复");}
            else if(kind.equals("therapists")){String id=text(row,"id",1,64),sid=text(row,"storeId",1,64);if(!id.matches("[A-Za-z0-9_-]+"))throw error(400,"调理师资料编号仅支持字母数字横线下划线");catalog.store(sid);var existing=d.rows("SELECT store_id FROM therapist WHERE id=?",id);if(!existing.isEmpty()&&!sid.equals(str(existing.get(0),"storeId")))throw error(400,"调理师已在其他门店，请通过调理师管理转店");text(row,"grade",0,80);text(row,"specialty",0,500);var serviceIds=Arrays.asList(text(row,"serviceIds",1,1000).split(","));for(String s:serviceIds)catalog.service(s.trim());for(String k:List.of("enabled","showOnClient","resting"))flag(row,k,!k.equals("resting"));if(!unique.add(id))throw error(400,"调理师资料编号重复");}
            else if(kind.equals("stores")){AdminService.validateStoreImport(row);if(!unique.add(str(row,"id")))throw error(400,"门店编号重复");}
            else{String id=text(row,"id",1,64);if(!id.matches("[A-Za-z0-9_-]+"))throw error(400,"品项编号无效");text(row,"description",0,3000);admin.safeImages(row);flag(row,"enabled",true);if(!unique.add(id))throw error(400,"品项编号重复");}
        }catch(org.springframework.web.server.ResponseStatusException e){errors.add("第"+row.get("_row")+"行："+e.getReason());}
        if(errors.size()>100)errors=new ArrayList<>(errors.subList(0,100));if(commit&&!errors.isEmpty())throw error(400,"文件未通过预检，未写入任何资料："+errors.get(0));if(commit){catalog.bookingLock();List<String> resources=new ArrayList<>();for(var row:rows){resources.add("store:"+str(row,"storeId"));resources.add("phone:"+str(row,"phone"));}catalog.guard(resources);for(var row:rows){if(kind.equals("members")){String phone=str(row,"phone"),sid=str(row,"storeId");var prev=d.rows("SELECT id FROM customer_profile WHERE phone=?",phone);String id=prev.isEmpty()?id():str(prev.get(0),"id");if(prev.isEmpty())d.update("INSERT INTO customer_profile VALUES(?,?,?,?,?,?,?,?,?)",id,phone,row.get("name"),flag(row,"memberVerified",false),str(row,"memberGrade"),sid,"",str(row,"externalId"),now());else d.update("UPDATE customer_profile SET name=?,member_verified=?,member_grade=?,external_id=? WHERE id=?",row.get("name"),flag(row,"memberVerified",false),str(row,"memberGrade"),str(row,"externalId"),id);if(d.count("SELECT COUNT(*) FROM store_customer WHERE store_id=? AND customer_profile_id=?",sid,id)==0)d.update("INSERT INTO store_customer VALUES(?,?,?,?,?)",sid,id,"","IMPORT",null);CustomerProfiles.source(d,id,"IMPORT");}
            else if(kind.equals("therapists")){String id=str(row,"id"),sid=str(row,"storeId");var previous=d.rows("SELECT * FROM therapist WHERE id=?",id);Map<String,Object> profile=previous.isEmpty()?new LinkedHashMap<>():d.object(previous.get(0).get("profileJson"));profile.put("sample",false);profile.put("grade",row.get("grade"));profile.put("specialty",row.get("specialty"));profile.put("serviceIds",Arrays.stream(str(row,"serviceIds").split(",")).map(String::trim).toList());profile.put("showOnClient",flag(row,"showOnClient",true));profile.put("resting",flag(row,"resting",false));profile.putIfAbsent("image","/media/ritual.webp");boolean enabled=flag(row,"enabled",true);if(d.count("SELECT COUNT(*) FROM therapist WHERE id=?",id)==0)d.update("INSERT INTO therapist VALUES(?,?,?,?,?)",id,sid,row.get("name"),d.stringify(profile),enabled);else{var old=d.one("SELECT store_id FROM therapist WHERE id=?",id);if(!sid.equals(str(old,"storeId")))throw error(409,"调理师已在其他门店，不能通过导入直接转店。");d.update("UPDATE therapist SET name=?,profile_json=?,enabled=? WHERE id=?",row.get("name"),d.stringify(profile),enabled,id);}}
            else if(kind.equals("stores")){admin.importStore(a,row);}
        }if(kind.equals("services")){var content=admin.content(a);var items=new ArrayList<>(catalog.collection(content,"services"));for(var row:rows){String id=str(row,"id");Map<String,Object> item=new LinkedHashMap<>(items.stream().filter(s->id.equals(str(s,"id"))).findFirst().orElse(Map.of("id",id,"english","WELLNESS RITUAL","tag","门店养护","steps",List.of("到店沟通","细致养护"))));for(String key:headers(kind))if(!key.equals("enabled"))item.put(key,row.get(key));item.put("enabled",flag(row,"enabled",true));items.removeIf(s->id.equals(str(s,"id")));items.add(item);}content.put("services",items);admin.saveContent(a,content,false);}d.audit(a,null,"import."+kind,kind,"成功处理="+rows.size()+"；品项保存为草稿待发布");}
        return Map.of("valid",errors.isEmpty(),"total",rows.size(),"errors",errors,"rows",rows.stream().limit(8).toList(),"imported",commit?rows.size():0,"servicesSavedAsDraft",kind.equals("services"));}
}
